    /** Names NavRegistry uses for sidebar pages. */
    private const ALIASES = [
        'inquiry' => 'message-square', 'occupancy' => 'line-chart', 'boarders' => 'users', 'rooms' => 'bed',
        'payments' => 'credit-card', 'expenses' => 'receipt', 'penalties' => 'scale', 'maintenance' => 'wrench',
        'incidents' => 'shield-alert',
    ];

    public static function svg(string $name, ?int $size = null, string $class = ''): string
    {
        $paths = self::PATHS[self::ALIASES[$name] ?? $name] ?? '<circle cx="12" cy="12" r="10"/>';
        $dim = $size === null ? '1em' : (string) $size;
        $classAttr = htmlspecialchars(trim('icon ' . $class));

        return '<svg class="' . $classAttr . '" xmlns="http://www.w3.org/2000/svg" width="' . $dim . '" height="' . $dim
            . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"'
            . ' stroke-linejoin="round" aria-hidden="true" focusable="false">' . $paths . '</svg>';
    }
